function sourceDragStart(event) {
  event.dataTransfer.effectAllowed = 'copy';
  var img = new Image();
  // Base64 encoding of a green circle.
  img.src = "data:image/png;base64,";
  event.dataTransfer.setDragImage(img, 50, 50);
  event.target.remove();
}

function addImage(event) {
  var img = document.createElement('img');
  img.setAttribute('src', event.dataTransfer.getData('text/uri-list').replace(
    /\r\n$/, ''));
  document.querySelector('div').appendChild(img);
}

// Draw navy/white concentric squares on the original canvas
var canvas = document.querySelector('canvas'),
  c = canvas.getContext('2d');
for (var x = 0; x != 50; x++) {
  c.fillStyle = (x % 2 == 0) ? 'navy' : 'white';
  c.beginPath();
  c.moveTo(x, x);
  c.lineTo(100 - x, x);
  c.lineTo(100 - x, 100 - x);
  c.lineTo(x, 100 - x);
  c.closePath();
  c.fill();
}

