    try {
      e.dataTransfer.allowTargetOrigin('http://example.com');
    } catch(e) {
      fails[fails.length] = 'allowTargetOrigin threw an error: '+e;
    }
  };
  orange.ondragenter = orange.ondragover = orange.ondrop = function (e) {
    e.preventDefault();
    evtdone[e.type] = true;
  };
