    const codePoints = [];
    let i = includeNull ? 0 : 1;
    for (; i

0x82; i++) {
      codePoints.push(String.fromCharCode(i));
    }
    a.href = `${scheme}:${codePoints.join("")}`;
    a.target = "_blank";
