  window.scrollTo(0, 0);
  setFeatureState(iframeElement, "vertical-scroll", "*");
  await loadUrlInIframe(iframeElement, url);
  await sendMessageAndGetResponse(iframeElement.contentWindow,
                                  {
                                    event_type: "touchmove",
                                    query: "#blocker",
                                    prevent: true
                                  });

